#!/usr/bin/env python3
"""Verify launcher API bridge with a host-side facade, not a device."""
import subprocess,tempfile
from pathlib import Path
sources={
'android/app/Activity.java': 'package android.app; public class Activity {}',
'org/levimc/launcher/core/mods/inbuilt/UnifiedMod.java': '''package org.levimc.launcher.core.mods.inbuilt; public class UnifiedMod { public final String id; public boolean enabled; public boolean fail; public UnifiedMod(String i,boolean b){id=i;enabled=b;} public String getId(){return id;} public String getName(){return "Name "+id;} public String getGroupName(){return "Built in";} public boolean isEnabled(){return enabled;} public void applyEnabled(boolean b){if(fail)throw new RuntimeException();enabled=b;} }''',
'org/levimc/launcher/core/mods/inbuilt/InbuiltModuleProvider.java': '''package org.levimc.launcher.core.mods.inbuilt; import java.util.*; import android.app.Activity; public class InbuiltModuleProvider {public static UnifiedMod first=new UnifiedMod("fps",false); public static List<UnifiedMod> load(Activity a){return Arrays.asList(first);} }''',
'org/levimc/launcher/core/mods/inbuilt/ExternalModuleProvider.java': '''package org.levimc.launcher.core.mods.inbuilt; import java.util.*; import android.app.Activity; public class ExternalModuleProvider {public static boolean fail; public static UnifiedMod external=new UnifiedMod("external",true); public static List<UnifiedMod> load(Activity a){if(fail)throw new RuntimeException();return Arrays.asList(external);} }''',
'org/levimc/launcher/core/mods/Mod.java': '''package org.levimc.launcher.core.mods; public class Mod {public final String id; public boolean on; public Mod(String i,boolean b){id=i;on=b;} public String getId(){return id;} public String getDisplayName(){return "Package "+id;} public boolean isEnabled(){return on;} }''',
'com/google/gson/Gson.java': '''package com.google.gson; import java.io.*; import java.util.*; public class Gson {public Object fromJson(Reader r,Class c)throws Exception {BufferedReader b=new BufferedReader(r);String line=b.readLine();if(line==null)return null; Map<String,Object> m=new HashMap<>();String[] a=line.split(",");m.put("name",a[0]);m.put("enabled",Boolean.valueOf(a[1]));return Arrays.asList(m);}}''',
'org/levimc/launcher/core/mods/ModManager.java': '''package org.levimc.launcher.core.mods; import java.util.*; import java.io.*; import com.google.gson.Gson; public class ModManager {static final ModManager I=new ModManager(); public Mod mod=new Mod("p1",true); private File configFile; private final Gson gson=new Gson(); public boolean write=true; public ModManager(){try{configFile=File.createTempFile("mod-config", ".json");configFile.deleteOnExit();save();}catch(Exception e){throw new RuntimeException(e);}} private void save(){try(FileWriter f=new FileWriter(configFile)){f.write("p1,"+mod.on);}catch(Exception e){throw new RuntimeException(e);}} public boolean bound=true;public int changes; public static ModManager getInstance(){return I;} public Object getCurrentVersion(){return bound?this:null;} public List<Mod> getMods(){return Arrays.asList(mod);} public void setModEnabled(String id,boolean b){if(mod.id.equals(id)){mod.on=b;changes++;if(write)save();}} }''',
'luma/ui/ModBridgeTest.java': '''package luma.ui; import android.app.Activity; import org.levimc.launcher.core.mods.ModManager; import org.levimc.launcher.core.mods.inbuilt.*; public class ModBridgeTest {static void check(boolean v){if(!v)throw new AssertionError();} public static void main(String[] a){ModBridge.Result m=ModBridge.modules(new Activity());check(m.available&&!m.partial&&m.rows.size()==2&&!m.rows.get(0).enabled);check(ModBridge.toggle(m.rows.get(0))&&InbuiltModuleProvider.first.enabled);InbuiltModuleProvider.first.fail=true;check(!ModBridge.toggle(ModBridge.modules(new Activity()).rows.get(0)));ExternalModuleProvider.fail=true;m=ModBridge.modules(new Activity());check(m.available&&m.partial&&m.rows.size()==1);ModBridge.Result p=ModBridge.packages();check(p.available&&p.rows.size()==1&&p.rows.get(0).enabled);check(ModBridge.toggle(p.rows.get(0))&&!ModManager.getInstance().mod.on);check(!ModBridge.toggle(p.rows.get(0)));check(ModManager.getInstance().changes==1);ModManager.getInstance().write=false;check(!ModBridge.toggle(ModBridge.packages().rows.get(0)));ModManager.getInstance().bound=false;check(!ModBridge.packages().available);System.out.println("launcher module and next-launch package bridge tests passed");}}'''
}
with tempfile.TemporaryDirectory() as temp:
 root=Path(temp)
 for name,content in sources.items():
  path=root/'src'/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
 out=root/'classes';out.mkdir()
 subprocess.run(['javac','-encoding','UTF-8','-d',str(out),*map(str,(root/'src').rglob('*.java')),'src/ModBridge.java'],check=True)
 subprocess.run(['java','-cp',str(out),'luma.ui.ModBridgeTest'],check=True)
